  if (/^\d+$/.test(s)) {
    return parseInt(s, 10);
  }

  // With units: sequence of (number+unit) separated by nothing, whitespace, or ", "
  const pattern = /^\d+[hms](?:(?:\s*|,\s+)\d+[hms])*$/;
  if (!pattern.test(s)) {
    throw new Error(`invalid duration: ${s}`);
  }

