  let total = 0;
  for (const comp of components) {
    const num = parseInt(comp.slice(0, -1), 10);
    const unit = comp.slice(-1);
    if (unit === 'h') total += num * 3600;
    else if (unit === 'm') total += num * 60;
    else if (unit === 's') total += num;
  }
  return total;
