	var sb strings.Builder
	flush := func() {
		if sb.Len() > 0 {
			word := strings.ToLower(sb.String())
			result[word]++
			sb.Reset()
		}
	}

	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			sb.WriteRune(r)
		} else {
			flush()
		}
	}
	flush()

	return result
}

