export function parseDuration(s: string): number {
  // Case 1: bare number (seconds only)
  if (/^\d+$/.test(s)) {
    return parseInt(s, 10);
  }

  // Case 2: one or more "<number><unit>" components,
  // separated by nothing, whitespace, or comma+whitespace.
  const fullPattern = /^(\d+[hms])((?:\s+|,\s+)?\d+[hms])*$/;
  if (!fullPattern.test(s)) {
    throw new Error(`invalid duration: ${s}`);
  }

  const componentPattern = /(\d+)([hms])/g;
  let total = 0;
  let match: RegExpExecArray | null;

  while ((match = componentPattern.exec(s)) !== null) {
    const value = parseInt(match[1], 10);
    const unit = match[2];

    switch (unit) {
      case 'h':
        total += value * 3600;
        break;
      case 'm':
        total += value * 60;
        break;
      case 's':
        total += value;
        break;
      default:
        // Should be unreachable due to regex constraints
        throw new Error(`invalid duration: ${s}`);
    }
  }

  return total;
}

export function parseDuration(s: string): number {
  const original = s;

  if (typeof s !== 'string' || s.length === 0) {
    throw new Error(`invalid duration: ${original}`);
  }

  interface Comp {
    start: number;
    end: number;
    num: string;
    unit?: string;
  }

  const comps: Comp[] = [];
  const regex = /(\d+)([hms])?/g;
  let match: RegExpExecArray | null;

  while ((match = regex.exec(s)) !== null) {
    comps.push({
      start: match.index,
      end: regex.lastIndex,
      num: match[1],
      unit: match[2],
    });
  }

  if (comps.length === 0) {
    throw new Error(`invalid duration: ${original}`);
  }

  // Validate that the components together with allowed separators
  // cover the entire input string.
  let cursor = 0;
  for (let i = 0; i < comps.length; i++) {
    const c = comps[i];
    const gap = s.slice(cursor, c.start);

    if (i === 0) {
      if (gap.length > 0) {
        throw new Error(`invalid duration: ${original}`);
      }
    } else {
      // allowed separators: nothing, pure whitespace, or comma followed by whitespace
      if (!/^(,\s+|\s*)$/.test(gap)) {
        throw new Error(`invalid duration: ${original}`);
      }
    }

    cursor = c.end;
  }

  if (cursor !== s.length) {
    throw new Error(`invalid duration: ${original}`);
  }

  // A bare number (no unit) is only allowed if it's the sole component.
  if (comps.length > 1) {
    for (const c of comps) {
      if (!c.unit) {
        throw new Error(`invalid duration: ${original}`);
      }
    }
  }

  let total = 0;
  for (const c of comps) {
    const n = parseInt(c.num, 10);
    let mult: number;

    switch (c.unit) {
      case 'h':
        mult = 3600;
        break;
      case 'm':
        mult = 60;
        break;
      case 's':
        mult = 1;
        break;
      case undefined:
        mult = 1;
        break;
      default:
        throw new Error(`invalid duration: ${original}`);
    }

    total += n * mult;
  }

  return total;
}
